package com.studenttong.mobile;
import android.content.*;import android.database.*;import android.database.sqlite.*;import org.json.*;import java.util.*;
public final class Store extends SQLiteOpenHelper {
 public Store(Context c){super(c,"studenttong.db",null,1);setWriteAheadLoggingEnabled(true);}
 public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE accounts(id TEXT PRIMARY KEY,name TEXT,platform TEXT,entry TEXT,slot INTEGER UNIQUE)");d.execSQL("CREATE TABLE tasks(id TEXT PRIMARY KEY,aid TEXT,title TEXT,url TEXT,kind TEXT,state TEXT,position REAL DEFAULT 0,duration REAL DEFAULT 0)");d.execSQL("CREATE TABLE questions(id TEXT PRIMARY KEY,aid TEXT,title TEXT,type TEXT,options TEXT,answer TEXT,source TEXT,analysis TEXT,canon TEXT,wrong INTEGER DEFAULT 0)");d.execSQL("CREATE TABLE settings(aid TEXT,k TEXT,v TEXT,PRIMARY KEY(aid,k))");}
 public void onUpgrade(SQLiteDatabase d,int a,int b){throw new IllegalStateException("数据升级尚未支持");}
 public synchronized JSONObject addAccount(String name,String p,String entry)throws Exception{if(name.trim().isEmpty()||name.length()>50)throw new Exception("请输入账号名称");if(!Arrays.asList("chaoxing","yuketang").contains(p)||!trusted(entry,p))throw new Exception("请输入对应平台的HTTPS网址");int slot=0;try(Cursor c=getReadableDatabase().rawQuery("SELECT slot FROM accounts ORDER BY slot",null)){while(c.moveToNext()){if(c.getInt(0)==slot)slot++;}}if(slot>=16)throw new Exception("此版本支持16个独立账号空间");String id=UUID.randomUUID().toString();ContentValues v=new ContentValues();v.put("id",id);v.put("name",name.trim());v.put("platform",p);v.put("entry",entry.trim());v.put("slot",slot);getWritableDatabase().insertOrThrow("accounts",null,v);setSetting("_global","selected:"+p,id);return account(id);}
 public static boolean trusted(String url,String platform){try{java.net.URI u=new java.net.URI(url);String h=u.getHost();if(!"https".equals(u.getScheme())||h==null||u.getUserInfo()!=null||u.getPort()!=-1)return false;String[] roots="chaoxing".equals(platform)?new String[]{"chaoxing.com"}:new String[]{"yuketang.cn","gdufemooc.cn"};for(String r:roots)if(h.equals(r)||h.endsWith("."+r))return true;return false;}catch(Exception e){return false;}}
 public JSONObject account(String id)throws Exception{try(Cursor c=getReadableDatabase().rawQuery("SELECT * FROM accounts WHERE id=?",new String[]{id})){if(!c.moveToFirst())throw new Exception("账号不存在");return row(c);}}
 public JSONArray accounts(String p)throws Exception{return query("SELECT * FROM accounts WHERE platform=? ORDER BY slot",new String[]{p});}
 public String setting(String aid,String key,String fallback){try(Cursor c=getReadableDatabase().rawQuery("SELECT v FROM settings WHERE aid=? AND k=?",new String[]{aid,key})){return c.moveToFirst()?c.getString(0):fallback;}}
 public void setSetting(String aid,String key,String val){ContentValues v=new ContentValues();v.put("aid",aid);v.put("k",key);v.put("v",val);getWritableDatabase().insertWithOnConflict("settings",null,v,SQLiteDatabase.CONFLICT_REPLACE);}
 public JSONObject addTask(String aid,String title,String url,String kind)throws Exception{JSONObject a=account(aid);if(!trusted(url,a.getString("platform")))throw new Exception("任务地址不属于当前平台");String id=UUID.randomUUID().toString();ContentValues v=new ContentValues();v.put("id",id);v.put("aid",aid);v.put("title",title.isEmpty()?"学习页面":title);v.put("url",url);v.put("kind",kind);v.put("state","已暂停");getWritableDatabase().insertOrThrow("tasks",null,v);return task(aid,id);}
 public JSONObject task(String aid,String id)throws Exception{try(Cursor c=getReadableDatabase().rawQuery("SELECT * FROM tasks WHERE aid=? AND id=?",new String[]{aid,id})){if(!c.moveToFirst())throw new Exception("任务不属于当前账号");return row(c);}}
 public JSONArray tasks(String aid)throws Exception{return query("SELECT * FROM tasks WHERE aid=? ORDER BY rowid DESC",new String[]{aid});}
 public void taskState(String aid,String id,String state,double pos,double duration)throws Exception{task(aid,id);ContentValues v=new ContentValues();v.put("state",state);v.put("position",pos);v.put("duration",duration);getWritableDatabase().update("tasks",v,"aid=? AND id=?",new String[]{aid,id});}
 public void deleteTask(String aid,String id)throws Exception{JSONObject t=task(aid,id);if("进行中".equals(t.optString("state")))throw new Exception("请先停止任务");getWritableDatabase().delete("tasks","aid=? AND id=?",new String[]{aid,id});}
 public int addQuestions(String aid,JSONArray questions)throws Exception{account(aid);SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try{int count=0;for(int i=0;i<questions.length();i++){JSONObject q=questions.getJSONObject(i);String title=q.optString("title").trim();if(title.isEmpty()||title.length()>20000)continue;JSONArray opts=q.optJSONArray("options");if(opts==null)opts=new JSONArray();String type=q.optString("type","single");if(Arrays.asList("single","multiple").contains(type)&&(opts.length()==0||opts.length()>26))type="unknown";String id=UUID.nameUUIDFromBytes((aid+"|"+title+"|"+opts.toString()).getBytes("UTF-8")).toString();String answer=q.optString("platformAnswer");String source="平台公布答案";if(answer.isEmpty()){answer=q.optString("referenceAnswer");source=q.optString("referenceSource","参考答案");}ContentValues v=new ContentValues();v.put("id",id);v.put("aid",aid);v.put("title",title);v.put("type",type);v.put("options",opts.toString());v.put("answer",answer);v.put("source",answer.isEmpty()?"尚无答案":source);v.put("analysis",q.optString("explanation"));v.put("canon",q.optString("platformAnswer").isEmpty()?q.optString("referenceCanonical",canonical(answer)):q.optString("canonicalAnswer",canonical(answer)));if(q.optBoolean("needsVision",false))v.put("type","unknown");try(Cursor c=d.rawQuery("SELECT wrong,source,answer,canon FROM questions WHERE id=?",new String[]{id})){boolean exists=c.moveToFirst();v.put("wrong",exists?c.getInt(0):0);if(exists&&"平台公布答案".equals(c.getString(1))&&!"平台公布答案".equals(source)){v.put("source",c.getString(1));v.put("answer",c.getString(2));v.put("canon",c.getString(3));}}d.insertWithOnConflict("questions",null,v,SQLiteDatabase.CONFLICT_REPLACE);count++;}d.setTransactionSuccessful();return count;}finally{d.endTransaction();}}
 public JSONArray questions(String aid,boolean wrong)throws Exception{return query("SELECT * FROM questions WHERE aid=?"+(wrong?" AND wrong=1":"")+" ORDER BY rowid",new String[]{aid});}
 public boolean check(String aid,String id,String answer)throws Exception{try(Cursor c=getReadableDatabase().rawQuery("SELECT answer,canon FROM questions WHERE aid=? AND id=?",new String[]{aid,id})){if(!c.moveToFirst()||c.getString(0).isEmpty())throw new Exception("本题没有可判分答案");boolean ok=canonical(c.getString(1)==null||c.getString(1).isEmpty()?c.getString(0):c.getString(1)).equals(canonical(answer));if(!ok){ContentValues v=new ContentValues();v.put("wrong",1);getWritableDatabase().update("questions",v,"aid=? AND id=?",new String[]{aid,id});}return ok;}}
 public static String canonical(String s){s=s.trim().toUpperCase(Locale.ROOT);if(Arrays.asList("正确","对","TRUE","√").contains(s))return "TRUE";if(Arrays.asList("错误","错","FALSE","×").contains(s))return "FALSE";s=s.replaceAll("[\\s,，;；、]","");if(s.matches("[A-Z]+")){char[] a=s.toCharArray();Arrays.sort(a);return new String(a);}return s;}
 JSONArray query(String sql,String[] args)throws Exception{JSONArray out=new JSONArray();try(Cursor c=getReadableDatabase().rawQuery(sql,args)){while(c.moveToNext())out.put(row(c));}return out;}
 JSONObject row(Cursor c)throws Exception{JSONObject j=new JSONObject();for(int i=0;i<c.getColumnCount();i++)j.put(c.getColumnName(i),c.isNull(i)?JSONObject.NULL:c.getString(i));return j;}
 public static JSONArray importRows(JSONObject source)throws Exception{JSONArray rows=source.optJSONArray("questions");if(rows==null)throw new Exception("文件没有questions题目数组");if(rows.length()>20000)throw new Exception("单次导入最多20000题");return rows;}
 public void deleteAccountData(String aid){SQLiteDatabase d=getWritableDatabase();for(String t:new String[]{"tasks","questions","settings"})d.delete(t,"aid=?",new String[]{aid});d.delete("accounts","id=?",new String[]{aid});}
}
